import{_ as e,o as s,c as t,ai as n}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"PMS 项目管理系统","description":"","frontmatter":{},"headers":[],"relativePath":"instances/business/pms.md","filePath":"instances/business/pms.md"}'),r={name:"instances/business/pms.md"};function i(d,a,l,o,p,c){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="pms-项目管理系统" tabindex="-1">PMS 项目管理系统 <a class="header-anchor" href="#pms-项目管理系统" aria-label="Permalink to “PMS 项目管理系统”">​</a></h1><blockquote><p>✅ 已验证（OpenBiz 第 3 个独立消费者） · 所属模块：<a href="/my-vitepress-site/instances/business/">03 企业业务应用</a> · 模块优先级：第 1 位 · 工程 <code>openbiz-pms-app</code></p></blockquote><h2 id="📌-项目简介" tabindex="-1">📌 项目简介 <a class="header-anchor" href="#📌-项目简介" aria-label="Permalink to “📌 项目简介”">​</a></h2><p>PMS（Project Management System）管理「<strong>项目 → 任务 → 里程碑 → 看板</strong>」的协作全链路。它是「企业业务应用」里复用度最高的系统——任务状态机与工单模型天然同构，是验证「底座复用」方法论的首个项目。</p><blockquote><p>简称说明：PM 在行业里常指「项目经理 / 产品经理」这个角色，系统文档统一写 <strong>PMS</strong> 以避免歧义。</p></blockquote><ul><li><strong>面向用户</strong>：项目经理（立项 / 排期）、成员（领任务 / 推进）、干系人（看板 / 进度）</li><li><strong>核心价值</strong>：项目与任务有状态机约束、可按看板视图推进，替代散落的表格与群聊</li></ul><h2 id="🗺️-功能规划" tabindex="-1">🗺️ 功能规划 <a class="header-anchor" href="#🗺️-功能规划" aria-label="Permalink to “🗺️ 功能规划”">​</a></h2><h3 id="✅-已实现-e2e-已验证" tabindex="-1">✅ 已实现（E2E 已验证） <a class="header-anchor" href="#✅-已实现-e2e-已验证" aria-label="Permalink to “✅ 已实现（E2E 已验证）”">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>能做什么</th><th>证据</th></tr></thead><tbody><tr><td>项目生命周期</td><td><code>PLANNING → ACTIVE → COMPLETED</code>，<code>ACTIVE ⇄ ON_HOLD</code>，活动态 <code>→ CANCELLED</code></td><td>项目状态机 E2E</td></tr><tr><td>任务管理</td><td><code>TODO → IN_PROGRESS → DONE</code>，活动态 <code>→ CANCELLED</code>，<code>DONE → IN_PROGRESS</code>（重开）</td><td>任务状态机 E2E</td></tr><tr><td>里程碑</td><td><code>type=MILESTONE</code> 与 <code>TASK</code> 共用一张表</td><td>数据结构</td></tr><tr><td>看板视图</td><td><code>GET /api/pms/projects/{id}/board</code> 按状态分组</td><td>看板分组断言</td></tr><tr><td>非法流转拦截</td><td>完成后取消项目 / 任务均被拒 <code>ILLEGAL_PROJECT_TRANSITION</code> / <code>ILLEGAL_TASK_TRANSITION</code></td><td>E2E</td></tr><tr><td>多租户</td><td>复用 <code>openbiz-saas-core</code> + RuoYi 登录外壳</td><td>独立库 <code>openbiz_pms</code></td></tr></tbody></table><h3 id="📋-待做-规划" tabindex="-1">📋 待做 / 规划 <a class="header-anchor" href="#📋-待做-规划" aria-label="Permalink to “📋 待做 / 规划”">​</a></h3><ul><li>[ ] <strong>甘特图</strong>：时间轴视图、依赖关系、拖拽调整</li><li>[ ] <strong>工时管理</strong>：工时填报、统计</li><li>[ ] <strong>资源负载</strong>：成员工作量与排期冲突</li><li>[ ] <strong>评论 / 动态</strong>：任务下的讨论与操作时间线</li><li>[ ] <strong>行级数据权限</strong>：项目成员 / 角色的数据隔离</li><li>[ ] <strong>预算与成本</strong>：项目预算、实际成本对比</li></ul><h2 id="🏗️-技术架构" tabindex="-1">🏗️ 技术架构 <a class="header-anchor" href="#🏗️-技术架构" aria-label="Permalink to “🏗️ 技术架构”">​</a></h2><h3 id="平台-垂直定位" tabindex="-1">平台 + 垂直定位 <a class="header-anchor" href="#平台-垂直定位" aria-label="Permalink to “平台 + 垂直定位”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌ 垂直应用层（薄：领域模型 + 表单/流程配置）</span></span>
<span class="line"><span>│   CRM · ERP · PMS · OA · BPM · Form        ◀ 本页：PMS</span></span>
<span class="line"><span>├ 平台内核 · OpenBiz（一次建深，覆盖通用能力约 80%）</span></span>
<span class="line"><span>│   多租户/数据隔离 · RBAC/行级权限 · 工作流引擎 · 动态表单引擎</span></span>
<span class="line"><span>│   审计日志 · 消息通知中心 · 导入导出/报表 · 开放 API/SSO</span></span>
<span class="line"><span>└ 数据层 · MySQL 8 · Redis · 对象存储 · 消息队列</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>PMS 是<strong>薄垂直层</strong>：只实现项目 / 任务状态机与看板分组，其余复用平台内核。</p><h3 id="本模块内部结构" tabindex="-1">本模块内部结构 <a class="header-anchor" href="#本模块内部结构" aria-label="Permalink to “本模块内部结构”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Vue3 前端（项目 / 任务 / 看板）</span></span>
<span class="line"><span>   │ REST</span></span>
<span class="line"><span>Controller → Service（项目 &amp; 任务双状态机）→ Mapper</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>MySQL \`openbiz_pms\`（project / task，里程碑复用 task.type=MILESTONE）</span></span>
<span class="line"><span>   ▲ 复用 openbiz-saas-core（多租户）+ RuoYi 登录外壳</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="🧰-技术栈-开发语言" tabindex="-1">🧰 技术栈 / 开发语言 <a class="header-anchor" href="#🧰-技术栈-开发语言" aria-label="Permalink to “🧰 技术栈 / 开发语言”">​</a></h2><table tabindex="0"><thead><tr><th>分层</th><th>技术</th></tr></thead><tbody><tr><td>后端</td><td>Java 21 + Spring Boot 3 + MyBatis</td></tr><tr><td>前端</td><td>Vue 3 + TypeScript</td></tr><tr><td>数据库</td><td>MySQL 8（独立库 <code>openbiz_pms</code>）</td></tr><tr><td>底座</td><td>OpenBiz <code>openbiz-saas-core</code> + RuoYi 登录外壳</td></tr><tr><td>部署</td><td>独立端口 18083 + 独立库</td></tr></tbody></table><h2 id="✅-支持什么-能力边界" tabindex="-1">✅ 支持什么（能力边界） <a class="header-anchor" href="#✅-支持什么-能力边界" aria-label="Permalink to “✅ 支持什么（能力边界）”">​</a></h2><ul><li><strong>支持</strong>：项目生命周期、任务状态流转（含重开）、里程碑、按状态分组看板、非法流转拦截</li><li><strong>暂不支持</strong>：甘特图、工时、资源负载、评论动态、行级权限、预算成本</li></ul><h2 id="🚀-开发路线" tabindex="-1">🚀 开发路线 <a class="header-anchor" href="#🚀-开发路线" aria-label="Permalink to “🚀 开发路线”">​</a></h2><table tabindex="0"><thead><tr><th>里程碑</th><th>内容</th><th>状态</th></tr></thead><tbody><tr><td>M1</td><td>项目 + 任务 + 看板最小闭环（双状态机）</td><td>✅ 完成</td></tr><tr><td>M2</td><td>甘特图 + 任务依赖</td><td>📋 规划</td></tr><tr><td>M3</td><td>工时 + 资源负载</td><td>📋 规划</td></tr><tr><td>M4</td><td>评论动态 + 行级权限 + 预算</td><td>📋 规划</td></tr></tbody></table><h2 id="🔗-相关资源" tabindex="-1">🔗 相关资源 <a class="header-anchor" href="#🔗-相关资源" aria-label="Permalink to “🔗 相关资源”">​</a></h2><ul><li>平台内核：<a href="/my-vitepress-site/instances/platform.html">平台内核 · OpenBiz</a></li><li>实证记录：<a href="/my-vitepress-site/apps/openbiz/pms.html">OpenBiz 实战 › 项目管理系统</a></li><li>工程位置：<code>E:/8.cangku/for-job/openbiz-pms-app</code>（含 README 与 E2E 脚本）</li></ul><hr><p>上一级：<a href="/my-vitepress-site/instances/business/">03 企业业务应用</a> · <a href="/my-vitepress-site/instances/">实例总览</a></p>`,27)])])}const m=e(r,[["render",i]]);export{b as __pageData,m as default};
